mapper.select:
SELECT ppi.*, su.DESCRIPTION AS creation_name, (select wm_concat(hbt.description) from hls_bp_master_role h,hls_bp_type hbt where h.bp_id = bp.bp_id and hbt.bp_type = h.bp_type and hbt.bp_category = h.bp_category) bp_type, bp.bp_code, bp.bp_name, bp.bp_class, (select v.meaning from sys_code_value_b_v v where v.code = 'PLM.INSPECTION_TYPE' and v.code_value = ppi.inspection_type) as inspection_type_n,
case ppi.inspection_method when 'REGULAR' then '定期' else '不定期' end inspection_method_n FROM plm_postloan_inspection ppi LEFT JOIN sys_user su ON ppi.creation_user_id = su.USER_ID LEFT JOIN hls_bp_master bp ON ppi.bp_id = bp.bp_id
ppi.postLoan_inspection_id = #{postloanInspectionId}
AND ppi.bp_id = #{bpId}

SELECT hbm.bp_id, hbm.bp_code, hbm.bp_name, ppi.postLoan_inspection_id, ppi.inspection_date, ppi.inspect_frenquency, ppi.inspection_method, ppi.peer_staff, ppi.STATUS, ppi.inspection_type, ppi.inspection_year, ppi.inspection_month, ppi.expected_completion_date, ppi.start_date, ppi.end_date, ppi.project_manager, ppi.risk_examiner, ppi.postloan_inspection_createtime, ppi.inspectors, ppi.offsite_inspection, ppi.other_inspection, ppi.is_plane_check, (select v.meaning from sys_code_value_b_v v where v.code = 'PLM.INSPECTION_TYPE' and v.code_value = ppi.inspection_type) as inspection_type_n,
case ppi.inspection_method when 'REGULAR' then '定期' else '不定期' end inspection_method_n,
(select hds.description from hls_document_status hds where hds.status_code= ppi.STATUS and hds.document_category='PRJ_PROJECT') status_n,
ppi.fin_statement_hd_id
FROM plm_postloan_inspection ppi LEFT JOIN hls_bp_master hbm ON ppi.bp_id = hbm.bp_id
AND ppi.inspection_year = #{inspectionYear}
AND ppi.inspection_month = #{inspectionMonth}
AND (hbm.bp_name like concat(concat('%',#{bpName}),'%') OR hbm.bp_code like concat(concat('%',#{bpName}),'%'))
AND ppi.STATUS =#{status,jdbcType=VARCHAR}
AND ppi.inspection_type IN
#{item}

SELECT su.user_id, su.description, fop.position_code, fop.position_name, sua.company_id FROM sys_user su, sys_user_allocation sua, fnd_employee_assigns fea, fnd_org_position fop
su.USER_ID = sua.user_id AND sua.employee_assign_id = fea.employee_assign_id AND fea.position_id = fop.position_id AND fop.position_code IN ( 'ADMIN', '10', '20', '30', '100', '105', '110', '120' )
AND su.user_id = #{userId}
AND sua.company_id = #{companyId}

SELECT c.* FROM ( SELECT cc.contract_id, cc.contract_number, cc.company_id, cc.tenant_id AS bp_id, cc.CREATED_BY FROM con_contract cc WHERE 1=1
AND cc.tenant_id = #{bpId}
AND cc.created_by = #{userId}
AND cc.company_id = #{companyId}
UNION ALL SELECT fct.contract_id, fct.contract_number, fct.company_id, fpb.bp_id, fct.CREATED_BY FROM fct_contract fct LEFT JOIN fct_project_bp fpb ON fct.project_id = fpb.project_id
fpb.bp_role_type = 'SELLER' AND fct.data_class = 'NORMAL'
AND fpb.bp_id = #{bpId}
AND fct.created_by = #{userId}
AND fct.company_id = #{companyId}
) c
